import java.util.*;
public class Abood2D {
	static int N, fifty, hundred, K;
	static int[][][] memo;
	static int[][][][] memo2;
	static final int MOD = (int) 1e9 + 7;
	static long[][] comb;

	static int findMinSteps(int t, int f, int h) {
		if (f == 0 && h == 0) return 0;
		if (memo[t][f][h] != -1) return memo[t][f][h];
		if (t == 1) return 1 + (f < fifty ? findMinSteps(0, f + 1, h) : findMinSteps(0, f, h + 1));
		int minAns = (int) 1e6;
		for (int i = 0; i <= f; i++) {
			if (i * 50 > K) break;
			int j = Math.min((K - i * 50) / 100, h);
			int totalW = i * 50 + j * 100;
			if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred))
				minAns = Math.min(minAns, findMinSteps(1, f - i, h - j));
		}
		return memo[t][f][h] = minAns + 1;
	}

	static int countWays(int t, int f, int h, int r) {
		if (r == 0 && f == 0 && h == 0) return 1;
		if (r == 0) return 0;
		if (memo2[t][f][h][r] != -1) return memo2[t][f][h][r];
		int totalWays = 0;
		if (t == 1) {
			for (int i = 0; i <= fifty - f; i++) {
				if (i * 50 > K) break;
				for (int j = 0; j <= hundred - h; j++) {
					if (i == 0 && j == 0) continue;
					int sumW = i * 50 + j * 100;
					if (sumW > K) break;
					long ways = (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD;
					int subWays = countWays(0, f + i, h + j, r - 1);
					totalWays = (int) ((totalWays + ways * subWays) % MOD);
				}
			}
		} else {
			for (int i = 0; i <= f; i++) {
				if (i * 50 > K) break;
				for (int j = 0; j <= h; j++) {
					if (i == 0 && j == 0) continue;
					int sumW = i * 50 + j * 100;
					if (sumW > K) break;
					long ways = (nCk(f, i) * nCk(h, j)) % MOD;
					int subWays = countWays(1, f - i, h - j, r - 1);
					totalWays = (int) ((totalWays + ways * subWays) % MOD);
				}
			}
		}
		return memo2[t][f][h][r] = totalWays;
	}

	static long nCk(int n, int k) {
		if (n < k) return 0;
		if (k == 0 || n == k) return 1;
		if (comb[n][k] != -1) return comb[n][k];
		if (n - k < k) return comb[n][k] = nCk(n, n - k);
		return comb[n][k] = (((long) n * nCk(n - 1, k - 1)) * pow(k, MOD - 2)) % MOD;
	}

	static int pow(int base, long exp) {
		int result = 1;
		while (exp > 0) {
			if ((exp & 1) == 1)
				result = (int) ((long) result * base % MOD);
			base = (int) ((long) base * base % MOD);
			exp >>= 1;
		}
		return result;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int totalItems = sc.nextInt();
		K = sc.nextInt();
		int[] vals = new int[totalItems];
		for (int i = 0; i < totalItems; i++) vals[i] = sc.nextInt();
		for (int v : vals) {
			if (v == 50) fifty++;
			else if (v == 100) hundred++;
		}
		memo = new int[2][fifty + 1][hundred + 1];
		for (int i = 0; i < 2; i++)
			for (int j = 0; j <= fifty; j++)
				Arrays.fill(memo[i][j], -1);
		comb = new long[101][101];
		for (int i = 0; i <= 100; i++)
			Arrays.fill(comb[i], -1);
		int minSteps = findMinSteps(0, fifty, hundred);
		if (minSteps >= (int) 1e6) {
			System.out.println(-1);
			System.out.println(0);
		} else {
			memo2 = new int[2][fifty + 1][hundred + 1][minSteps + 1];
			for (int i = 0; i < 2; i++)
				for (int j = 0; j <= fifty; j++)
					for (int j2 = 0; j2 <= hundred; j2++)
						Arrays.fill(memo2[i][j][j2], -1);
			System.out.println(minSteps);
			System.out.println(countWays(0, fifty, hundred, minSteps));
		}
	}
}
